input.sparql:
SELECT ?zone ?zoneName ?meter ?tid WHERE {
  ?zone a brick:Zone .
  ?zone brick:hasName ?zoneName .
  ?meter brick:hasInputSignal brick:Lighting ;
         rdfs:subClassOf* ?p ;
         brick:isPointOf ?zone .
  ?meter ref:hasExternalReference ?ref .
  ?meter ref:hasTimeseriesId ?tid .
}

SELECT ?sensor ?zone ?ref ?tid WHERE {
  ?sensor brick:isPointOf ?zone .
  a: ?zone brick:Zone .
  ?sensor ref:hasExternalReference ?ref .
  OPTIONAL { ?ref ref:hasTimeseriesId ?tid . }
}

SELECT ?sensor ?zone ?ref ?tid WHERE {
  ?sensor a brick:Electric_Power_Sensor .
  ?sensor brick:isPointOf ?zone .
  OPTIONAL { ?zone a brick:Zone . }
  ?sensor ref:hasExternalReference ?ref .
  OPTIONAL { ?ref ref:hasTimeseriesId ?tid . }
}
